function Dashboard({ widgets, theme }: Props) {
  if (!widgets) return <Spinner />;

  // hook called after an early return
  const sorted = useMemo(
    () => widgets.sort((a, b) => a.order - b.order),
    [widgets],
  );

  const onSelect = (id: string) => track('select', id);

  return (
    <Grid theme={theme}>
      {sorted.map((w) => (
        <Widget key={w.id} widget={w} onSelect={onSelect} />
      ))}
    </Grid>
  );
}
